let gameOver = false;

// 物理常量
const GRAVITY = 0.6;
const GROUND_Y = 350;
const JUMP_FORCE = -15;

// 粒子系统
let particles = [];

class Particle {
    constructor(x, y, color, vx, vy, size, life) {
        this.x = x;
        this.y = y;
        this.color = color;
        this.vx = vx;
        this.vy = vy;
        this.size = size;
        this.life = life;
        this.maxLife = life;
    }

    update() {
        this.x += this.vx;
        this.y += this.vy;
        this.vy += 0.2;
        this.life--;
    }

    draw() {
        const alpha = this.life / this.maxLife;
        ctx.globalAlpha = alpha;
        ctx.fillStyle = this.color;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size * alpha, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
    }
}

function createHitParticles(x, y, color) {
    for (let i = 0; i < 12; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 4 + 2;
        particles.push(new Particle(x, y, color, Math.cos(angle) * speed, Math.sin(angle) * speed - 2, Math.random() * 3 + 2, 25));
    }
}

function createDustParticles(x, y) {
    for (let i = 0; i < 4; i++) {
        particles.push(new Particle(x + Math.random() * 20 - 10, y, '#666', Math.random() * 1 - 0.5, -Math.random() * 1.5, Math.random() * 2 + 1, 15));
    }
}

