let gameOver = false;
const GRAVITY = 0.6;
const GROUND_Y = 350;
const JUMP_FORCE = -15;

let particles = [];

class Particle {
    constructor(x, y, color, vx, vy, size, life) {
        this.x = x; this.y = y; this.color = color;
        this.vx = vx; this.vy = vy; this.size = size;
        this.life = life; this.maxLife = life;
    }
    update() {
        this.x += this.vx; this.y += this.vy; this.vy += 0.2; this.life--;
    }
    draw() {
        ctx.globalAlpha = this.life / this.maxLife;
        ctx.fillStyle = this.color;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size * (this.life / this.maxLife), 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
    }
}

function createHitParticles(x, y, color) {
    for (let i = 0; i < 10; i++) {
        const a = Math.random() * Math.PI * 2;
        const s = Math.random() * 4 + 2;
        particles.push(new Particle(x, y, color, Math.cos(a) * s, Math.sin(a) * s - 2, 
                                   Math.random() * 3 + 2, 20));
    }
}

function createDust(x, y) {
    for (let i = 0; i < 3; i++) {
        particles.push(new Particle(x + Math.random() * 20 - 10, y, '#666', 
                                   Math.random() - 0.5, -Math.random(), 
                                   Math.random() * 2 + 1, 12));
    }
}

class Player {
    constructor(x, color, name) {
        this.x = x; this.y = GROUND_Y;
        this.width = 50; this.height = 80;
        this.color = color; this.name = name;
        this.vx = 0; this.vy = 0;
        this.health = 100;
        this.isJumping = false;
        this.isAttacking = false;
        this.attackCooldown = 0;
        this.facingRight = x < canvas.width / 2;
        this.animFrame = 0; this.animTimer = 0;
        this.isMoving = false;
        this.hitFlash = 0;
    }

    update() {
        this.vy += GRAVITY;
        this.x += this.vx; this.y += this.vy;

        if (this.y >= GROUND_Y) {
            if (this.isJumping) createDust(this.x + 25, GROUND_Y);
            this.y = GROUND_Y; this.vy = 0; this.isJumping = false;
        }

        if (this.x < 0) this.x = 0;
        if (this.x + this.width > canvas.width) this.x = canvas.width - this.width;

        if (this.attackCooldown > 0) {
            this.attackCooldown--;
            if (this.attackCooldown === 0) this.isAttacking = false;
        }

        if (this.hitFlash > 0) this.hitFlash--;

        this.animTimer++;
        if (this.animTimer > 5) {
            this.animTimer = 0; 
            this.animFrame = (this.animFrame + 1) % 4;
        }

        this.vx *= 0.85;
        this.isMoving = Math.abs(this.vx) > 0.5;
    }

    draw() {
