const keys = {};

document.addEventListener('keydown', (e) => {
    keys[e.key.toLowerCase()] = true;

    if (e.key.toLowerCase() === 'r' && !gameRunning) {
        startGame();
    }

    if (e.key.toLowerCase() === 'w') player1.jump();
    if (e.key === 'ArrowUp') player2.jump();
    if (e.key.toLowerCase() === 'f') player1.attack();
    if (e.key.toLowerCase() === 'm') player2.attack();

    e.preventDefault();
