    const attackRange = 60;
    const p1AttackX = p1.facingRight ? p1.x + p1.width : p1.x - attackRange;
    const p1AttackY = p1.y - p1.height / 2;

    return p1.isAttacking && 
           p1AttackX < p2.x + p2.width &&
           p1AttackX + attackRange > p2.x &&
           p1AttackY < p2.y &&
           p1AttackY + p1.height > p2.y - p2.height;
